a=yaml.safe_load(open('case/recorded_config.yaml'))
b=yaml.safe_load(open('outputs/2026-10-28/22-22-39/.hydra/config.yaml'))
def flat(d,p=''):
    out={}
    if isinstance(d,dict):
        for k,v in d.items(): out.update(flat(v,p+'/'+str(k) if p else str(k)))
    elif isinstance(d,list):
        out[p]=str(d)
    else: out[p]=d
    return out
fa,fb=flat(a),flat(b)
keys=sorted(set(fa)|set(fb))
